import React, { useState, useEffect } from "react";
import { Link, useNavigate } from "react-router-dom"; 
import { getAuth, onAuthStateChanged, signOut } from "firebase/auth";
import { getDatabase, ref, onValue } from "firebase/database"; 
import "./Navbar.css"; 

function Navbar() {
  const [user, setUser] = useState(null);
  const [notifications, setNotifications] = useState(0);
  const [menuOpen, setMenuOpen] = useState(false); // ✅ เพิ่ม state สำหรับ Hamburger Menu
  const navigate = useNavigate();

  useEffect(() => {
    const auth = getAuth();
    const unsubscribe = onAuthStateChanged(auth, (currentUser) => {
      setUser(currentUser);
    });

    // ✅ ฟังก์ชันตรวจสอบการแจ้งเตือนจาก Firebase Realtime Database
    if (user) {
      const db = getDatabase();
      const notificationsRef = ref(db, 'notifications/' + user.uid);
      onValue(notificationsRef, (snapshot) => {
        const data = snapshot.val();
        setNotifications(data ? Object.keys(data).length : 0);
      });
    }

    return () => unsubscribe();
  }, [user]);

  const handleLogout = async () => {
    const auth = getAuth();
    await signOut(auth);
    setUser(null);
    navigate("/login");
  };

  return (
    <nav className="navbar">
      <div className="navbar-brand">
        <Link to="/" className="navbar-link">Restaurant System</Link>
      </div>

      {/* ✅ Hamburger Menu สำหรับจอเล็ก */}
      <div className="menu-toggle" onClick={() => setMenuOpen(!menuOpen)}>
        <div></div>
        <div></div>
        <div></div>
      </div>

      <div className={`navbar-links ${menuOpen ? 'active' : ''}`}>
        <Link to="/" className="navbar-link">Home</Link>
        <Link to="/menu" className="navbar-link">Menu</Link>
        <Link to="/orders" className="navbar-link">Orders</Link>
        
        {user && (
          <>
            <Link to="/notifications" className="navbar-link">
              Notifications
              {notifications > 0 && (
                <span className="notification-badge">{notifications}</span>
              )}
            </Link>
            <span className="navbar-user">Hello, {user.displayName || "User"}</span>
            <button onClick={handleLogout} className="navbar-link logout-btn">Logout</button>
          </>
        )}

        {!user && (
          <button onClick={() => navigate('/login')} className="navbar-link login-register-btn">Login</button>
        )}
      </div>
    </nav>
  );
}

export default Navbar;
